const int RED = 9;
const int GREEN = 10;
const int BLUE = 11;

void setup() {
  pinMode(RED, OUTPUT);
  pinMode(GREEN, OUTPUT);
  pinMode(BLUE, OUTPUT);
}

void color(int r, int g, int b) {
  analogWrite(RED, r);
  analogWrite(GREEN, g);
  analogWrite(BLUE, b);
}

void loop() {

  color(255, 0, 0);      
  delay(1000);

  color(0, 255, 0);      
  delay(1000);

  color(0, 0, 255);      
  delay(1000);

  color(255, 255, 0);     
  delay(1000);

  color(255, 0, 255);    
  delay(1000);

  color(0, 255, 255);    
  delay(1000);

  color(255, 255, 255);  
  delay(1000);

  color(255, 128, 0);     
  delay(1000);

  color(128, 0, 255);     
  delay(1000);

  color(255, 0, 128);     
  delay(1000);

  color(128, 255, 0);    
  delay(1000);

  color(0, 128, 255);     
  delay(1000);

  color(128, 128, 128);   
  delay(1000);

  color(255, 128, 128);   
  delay(1000);

  color(128, 255, 128);   
  delay(1000);

  color(128, 128, 255);   
  delay(1000);
}
